/**
 * Load a maximal example of {@link types.LangString} from
 * the test data directory.
 */
export function loadMaximalLangString(
): OurTypes.LangString {
  const aPath = path.join(
    TestCommon.TEST_DATA_DIR,
    "Json",
    "Expected",
    "LangString",
    "maximal.json"
  );

  const jsonable = TestCommon.readJsonFromFileSync(aPath);

  const instanceOrError = OurJsonization.langStringFromJsonable(
    jsonable
  );
  expect(instanceOrError.error).toBeNull();
  const instance = instanceOrError.mustValue();

  const casted = OurTypes.asLangString(instance);
  if (casted === null) {
    throw new Error(
      `Expected instance of LangString in ${aPath}, ` +
      `but got: ${typeof instance}`
    );
  }
  return casted;
}

